// Generated from the exact PNG exports in assets/figma. Embedded so the
// existing single-executable distribution does not lose its image resources.
// Source: https://www.figma.com/design/Tr6hAfLgUAulbXkagRyX3S
import AppKit

@MainActor enum MenuBarAssets {
    static func image(_ name: String, size: CGFloat = 18) -> NSImage {
        let image = NSImage(data: Data(base64Encoded: png[name]!)!)!
        image.size = NSSize(width: size, height: size)
        image.isTemplate = true
        return image
    }

    private static let png: [String: String] = [
        "status-enabled": "",
        "status-paused": "",
        "status-attention": "",
        "eye": "",
        "cursor": "",
        "app": "",
        "browser": "",
        "preview": "",
        "log": "",
        "lock": "",
        "quit": "",
    ]
}
